#include <array>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <random>
#include <cmath>
#include <chrono>
#include <cstdlib>
using namespace std;
using TT=array<uint64_t,16>;
struct Gate{int a,b,ca,cb;};struct Circuit{vector<Gate>g;int out=0;};
mt19937_64 rng(2592);TT inp[10],target,mask2,mask3;vector<pair<int,int>>edges;int B=17;
int rr(int n){return rng()%n;}
int eval(const Circuit&c,int weighted=0){TT w[32];copy(inp,inp+10,w);for(int i=0;i<(int)c.g.size();i++){auto[a,b,ca,cb]=c.g[i];for(int j=0;j<16;j++)w[10+i][j]=(w[a][j]^(ca?UINT64_MAX:0))&(w[b][j]^(cb?UINT64_MAX:0));}int score=0;for(int j=0;j<16;j++){uint64_t d=w[9+c.g.size()][j]^target[j]^(c.out?UINT64_MAX:0);score+=__builtin_popcountll(d);if(weighted)score+=4*__builtin_popcountll(d&mask2[j])+2*__builtin_popcountll(d&mask3[j]);}return score;}
Circuit initial(){array<array<int,4>,5>is={{{0,2,8,9},{0,3,6,7},{1,3,5,9},{1,4,7,8},{2,4,5,6}}};bool chosen[10]={};for(auto v:is[rr(5)])chosen[v]=true;vector<int>nbr[10];for(auto[a,b]:edges){if(chosen[a]||(!chosen[b]&&rr(2)))swap(a,b);nbr[a].push_back(b);}vector<int>centers;for(int i=0;i<10;i++)if(nbr[i].size())centers.push_back(i);shuffle(centers.begin(),centers.end(),rng);Circuit c;vector<int>terms;int phase[32]={};auto add=[&](int op,int a,int b){c.g.push_back({a,b,phase[a]^op,phase[b]^op});int j=9+c.g.size();phase[j]=op;return j;};for(int a:centers){auto ns=nbr[a];shuffle(ns.begin(),ns.end(),rng);int p=ns[0];for(int i=1;i<(int)ns.size();i++)p=add(1,p,ns[i]);terms.push_back(add(0,a,p));}shuffle(terms.begin(),terms.end(),rng);int p=terms[0];for(int i=1;i<(int)terms.size();i++)p=add(1,p,terms[i]);c.out=phase[p];if(c.g.size()!=20||eval(c)!=0){fprintf(stderr,"Bad base\n");exit(2);}while((int)c.g.size()>B){int i=rr(c.g.size()-1),r=rr(2);int rep=r?c.g[i].a:c.g[i].b,cs=r?c.g[i].ca:c.g[i].cb;c.g.erase(c.g.begin()+i);for(auto &g:c.g){if(g.a==10+i){g.a=rep;g.ca^=cs;}else if(g.a>10+i)--g.a;if(g.b==10+i){g.b=rep;g.cb^=cs;}else if(g.b>10+i)--g.b;}}return c;}
// A producer in cut may supply both its physical polarity and one shared NOT.
bool phases(const Circuit&c,uint32_t cut,vector<int>&p){int n=10+c.g.size();vector<pair<int,int>>ad[32];for(int i=0;i<B;i++){auto[a,b,ca,cb]=c.g[i];if(!(cut>>a&1)){ad[a].push_back({10+i,ca});ad[10+i].push_back({a,ca});}if(!(cut>>b&1)){ad[b].push_back({10+i,cb});ad[10+i].push_back({b,cb});}}p.assign(n,-1);vector<int>todo;for(int i=0;i<10;i++){p[i]=0;todo.push_back(i);}if(!(cut>>(n-1)&1)){p[n-1]=c.out;todo.push_back(n-1);}for(int step=0;step<=n;step++){if(step){if(p[step-1]>=0)continue;p[step-1]=0;todo.push_back(step-1);}while(!todo.empty()){int a=todo.back();todo.pop_back();for(auto[b,s]:ad[a]){if(p[b]>=0&&p[b]!=(p[a]^s))return false;if(p[b]<0){p[b]=p[a]^s;todo.push_back(b);}}}}return true;}
bool cost(const Circuit&c,int k,uint32_t&found,vector<int>&pol){int n=10+B;vector<int>sel(k);auto rec=[&](auto&&self,int last,int rem,uint32_t cut)->bool{if(rem==0){if(phases(c,cut,pol)){found=cut;return true;}return false;}for(int i=last;i<=n-rem;i++)if(self(self,i+1,rem-1,cut|(1U<<i)))return true;return false;};return rec(rec,0,k,0);}
void printc(const Circuit&c,int score){printf("score %d binary %zu output_sign %d\n",score,c.g.size(),c.out);for(int i=0;i<B;i++){auto[a,b,ca,cb]=c.g[i];printf("%d AND %d %d %d %d\n",10+i,a,ca,b,cb);}fflush(stdout);}
int main(int argc,char**argv){int sec=argc>1?atoi(argv[1]):600;B=argc>2?atoi(argv[2]):17;if(argc>3)rng.seed(atoll(argv[3]));for(int i=0;i<5;i++){edges.push_back({i,(i+1)%5});edges.push_back({i,i+5});}for(auto e:vector<pair<int,int>>{{5,7},{7,9},{9,6},{6,8},{8,5}})edges.push_back(e);for(int r=0;r<1024;r++){for(int i=0;i<10;i++)if(r>>i&1)inp[i][r/64]|=1ULL<<(r%64);bool t=false;for(auto[a,b]:edges)t|=(r>>a&1)&&(r>>b&1);if(t)target[r/64]|=1ULL<<(r%64);int w=__builtin_popcount((unsigned)r);if(w==2)mask2[r/64]|=1ULL<<(r%64);if(w==3)mask3[r/64]|=1ULL<<(r%64);}int best=99999,hits=0;long long attempts=0,restarts=0;auto start=chrono::steady_clock::now();while(chrono::duration<double>(chrono::steady_clock::now()-start).count()<sec){Circuit c=initial();int weighted=rr(2),s=eval(c,weighted);double temp=rr(4)==0?1.0:0.0;for(int k=0;k<100000;k++){int i=rr(B),t=rr(5);Gate old=c.g[i];int oldout=c.out;if(t==0)c.g[i].a=rr(10+i);if(t==1)c.g[i].b=rr(10+i);if(t==2)c.g[i].ca^=1;if(t==3)c.g[i].cb^=1;if(t==4)c.out^=1;int ns=eval(c,weighted);attempts++;if(ns<=s||(temp>0&&(double)rng()/UINT64_MAX<exp((s-ns)/temp)))s=ns;else{c.g[i]=old;c.out=oldout;}if(s<best){best=s;printc(c,eval(c));printf("weighted %d objective %d attempts %lld restarts %lld\n",weighted,s,attempts,restarts);fflush(stdout);}if(s==0){hits++;uint32_t cut;vector<int>pol;bool ok=cost(c,19-B,cut,pol);printf("HIT %d cost_bounded %d\n",hits,ok);if(ok){printc(c,0);printf("cut %u phases",cut);for(auto p:pol)printf(" %d",p);printf("\n");return 0;}break;}}restarts++;}printf("DONE attempts %lld restarts %lld best %d hits %d\n",attempts,restarts,best,hits);return 1;}
